import{_ as e,o as l,c as i,a2 as r}from"./chunks/framework.xlC3Vtar.js";const p=JSON.parse('{"title":"功能特性","description":"","frontmatter":{},"headers":[],"relativePath":"features.md","filePath":"features.md"}'),o={name:"features.md"};function h(t,a,d,n,c,s){return l(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h1><p>SnipX 提供截图、标注、贴图、取色、录屏和便携发布能力，适合需要轻量 Windows 截图工具的日常场景。</p><h2 id="📸-截图功能" tabindex="-1">📸 截图功能 <a class="header-anchor" href="#📸-截图功能" aria-label="Permalink to &quot;📸 截图功能&quot;">​</a></h2><h3 id="区域截图" tabindex="-1">区域截图 <a class="header-anchor" href="#区域截图" aria-label="Permalink to &quot;区域截图&quot;">​</a></h3><p>拖拽鼠标选择任意区域进行截图，支持实时显示选区尺寸。</p><p><strong>使用方法</strong>：</p><ol><li>按 <code>Alt+X</code> 启动区域截图</li><li>拖拽鼠标选择区域</li><li>按 <code>Enter</code> 确认，或松开鼠标完成选区</li></ol><p><strong>特性</strong>：</p><ul><li>✅ 实时显示选区尺寸</li><li>✅ 放大镜辅助精确选择</li><li>✅ 方向键微调选区（1px / 10px）</li><li>✅ 支持窗口边界检测</li></ul><hr><h3 id="全屏截图" tabindex="-1">全屏截图 <a class="header-anchor" href="#全屏截图" aria-label="Permalink to &quot;全屏截图&quot;">​</a></h3><p>一键截取整个虚拟桌面，支持多显示器。</p><p><strong>使用方法</strong>：</p><ul><li>按 <code>Alt+F</code> 进行全屏截图</li></ul><p><strong>特性</strong>：</p><ul><li>✅ 支持多显示器虚拟桌面</li><li>✅ 自动获取完整屏幕范围</li><li>✅ 截图后直接进入编辑器</li></ul><hr><h3 id="窗口检测" tabindex="-1">窗口检测 <a class="header-anchor" href="#窗口检测" aria-label="Permalink to &quot;窗口检测&quot;">​</a></h3><p>区域截图模式下移动鼠标到窗口上，SnipX 会自动识别并高亮窗口边界。</p><p><strong>使用方法</strong>：</p><ol><li>按 <code>Alt+X</code> 启动区域截图</li><li>移动鼠标到目标窗口</li><li>点击鼠标左键选择该窗口区域</li></ol><hr><h3 id="滚动截图" tabindex="-1">滚动截图 <a class="header-anchor" href="#滚动截图" aria-label="Permalink to &quot;滚动截图&quot;">​</a></h3><p>从托盘菜单触发，对当前前台窗口执行简化滚动截图。</p><p><strong>使用方法</strong>：</p><ol><li>激活需要截图的窗口</li><li>右键托盘图标，选择「滚动截图」</li><li>SnipX 会采集多段内容并拼接成长图</li></ol><hr><h2 id="🎨-标注工具-10-种" tabindex="-1">🎨 标注工具（10 种） <a class="header-anchor" href="#🎨-标注工具-10-种" aria-label="Permalink to &quot;🎨 标注工具（10 种）&quot;">​</a></h2><h3 id="_1-矩形工具" tabindex="-1">1. 矩形工具 <a class="header-anchor" href="#_1-矩形工具" aria-label="Permalink to &quot;1. 矩形工具&quot;">​</a></h3><p>绘制矩形边框，可调整颜色和粗细。</p><h3 id="_2-椭圆工具" tabindex="-1">2. 椭圆工具 <a class="header-anchor" href="#_2-椭圆工具" aria-label="Permalink to &quot;2. 椭圆工具&quot;">​</a></h3><p>绘制椭圆或圆形标注。</p><h3 id="_3-箭头工具" tabindex="-1">3. 箭头工具 <a class="header-anchor" href="#_3-箭头工具" aria-label="Permalink to &quot;3. 箭头工具&quot;">​</a></h3><p>添加箭头指示，支持多种箭头样式（→ ⇒ ➡ ⇢）。</p><h3 id="_4-铅笔工具" tabindex="-1">4. 铅笔工具 <a class="header-anchor" href="#_4-铅笔工具" aria-label="Permalink to &quot;4. 铅笔工具&quot;">​</a></h3><p>自由绘制线条，适合圈画重点。</p><h3 id="_5-文字工具" tabindex="-1">5. 文字工具 <a class="header-anchor" href="#_5-文字工具" aria-label="Permalink to &quot;5. 文字工具&quot;">​</a></h3><p>在截图上添加文字说明。</p><h3 id="_6-直线工具" tabindex="-1">6. 直线工具 <a class="header-anchor" href="#_6-直线工具" aria-label="Permalink to &quot;6. 直线工具&quot;">​</a></h3><p>绘制直线，可调整颜色和粗细。</p><h3 id="_7-序号标签" tabindex="-1">7. 序号标签 <a class="header-anchor" href="#_7-序号标签" aria-label="Permalink to &quot;7. 序号标签&quot;">​</a></h3><p>添加自动递增的序号标签，便于说明步骤。</p><h3 id="_8-高亮工具" tabindex="-1">8. 高亮工具 <a class="header-anchor" href="#_8-高亮工具" aria-label="Permalink to &quot;8. 高亮工具&quot;">​</a></h3><p>使用半透明高亮强调重点区域。</p><h3 id="_9-马赛克工具" tabindex="-1">9. 马赛克工具 <a class="header-anchor" href="#_9-马赛克工具" aria-label="Permalink to &quot;9. 马赛克工具&quot;">​</a></h3><p>像素化遮挡敏感信息。</p><h3 id="_10-模糊工具" tabindex="-1">10. 模糊工具 <a class="header-anchor" href="#_10-模糊工具" aria-label="Permalink to &quot;10. 模糊工具&quot;">​</a></h3><p>使用模糊效果柔和遮挡内容。</p><hr><h2 id="🔧-编辑功能" tabindex="-1">🔧 编辑功能 <a class="header-anchor" href="#🔧-编辑功能" aria-label="Permalink to &quot;🔧 编辑功能&quot;">​</a></h2><h3 id="选中标注" tabindex="-1">选中标注 <a class="header-anchor" href="#选中标注" aria-label="Permalink to &quot;选中标注&quot;">​</a></h3><p>点击标注对象即可选中，显示调整手柄。</p><h3 id="拖拽移动" tabindex="-1">拖拽移动 <a class="header-anchor" href="#拖拽移动" aria-label="Permalink to &quot;拖拽移动&quot;">​</a></h3><p>选中标注后，按住鼠标左键拖拽移动。</p><h3 id="调整大小" tabindex="-1">调整大小 <a class="header-anchor" href="#调整大小" aria-label="Permalink to &quot;调整大小&quot;">​</a></h3><p>选中标注后，拖拽调整手柄调整大小。</p><h3 id="删除标注" tabindex="-1">删除标注 <a class="header-anchor" href="#删除标注" aria-label="Permalink to &quot;删除标注&quot;">​</a></h3><p>选中标注后，按 <code>Delete</code> 或 <code>Backspace</code> 删除。</p><h3 id="撤销-重做" tabindex="-1">撤销/重做 <a class="header-anchor" href="#撤销-重做" aria-label="Permalink to &quot;撤销/重做&quot;">​</a></h3><ul><li><code>Ctrl+Z</code> 撤销</li><li><code>Ctrl+Y</code> 重做</li></ul><h3 id="工具快捷切换" tabindex="-1">工具快捷切换 <a class="header-anchor" href="#工具快捷切换" aria-label="Permalink to &quot;工具快捷切换&quot;">​</a></h3><p>编辑器支持数字键快速切换工具：<code>1</code> 到 <code>9</code> 和 <code>0</code>。</p><hr><h2 id="💾-保存功能" tabindex="-1">💾 保存功能 <a class="header-anchor" href="#💾-保存功能" aria-label="Permalink to &quot;💾 保存功能&quot;">​</a></h2><h3 id="png-格式" tabindex="-1">PNG 格式 <a class="header-anchor" href="#png-格式" aria-label="Permalink to &quot;PNG 格式&quot;">​</a></h3><p>无损压缩，适合保留截图细节。</p><h3 id="jpg-格式" tabindex="-1">JPG 格式 <a class="header-anchor" href="#jpg-格式" aria-label="Permalink to &quot;JPG 格式&quot;">​</a></h3><p>可调质量（1-100），适合照片类截图。</p><h3 id="bmp-格式" tabindex="-1">BMP 格式 <a class="header-anchor" href="#bmp-格式" aria-label="Permalink to &quot;BMP 格式&quot;">​</a></h3><p>无压缩位图格式，兼容性好。</p><h3 id="自动保存" tabindex="-1">自动保存 <a class="header-anchor" href="#自动保存" aria-label="Permalink to &quot;自动保存&quot;">​</a></h3><p>可在设置中启用自动保存，将截图保存到指定目录并使用时间戳命名。</p><hr><h2 id="📋-剪贴板功能" tabindex="-1">📋 剪贴板功能 <a class="header-anchor" href="#📋-剪贴板功能" aria-label="Permalink to &quot;📋 剪贴板功能&quot;">​</a></h2><h3 id="复制到剪贴板" tabindex="-1">复制到剪贴板 <a class="header-anchor" href="#复制到剪贴板" aria-label="Permalink to &quot;复制到剪贴板&quot;">​</a></h3><p>按 <code>Ctrl+C</code> 将当前编辑结果复制到剪贴板。</p><h3 id="双击复制" tabindex="-1">双击复制 <a class="header-anchor" href="#双击复制" aria-label="Permalink to &quot;双击复制&quot;">​</a></h3><p>双击截图区域可快速复制并退出。</p><hr><h2 id="🎯-取色器功能" tabindex="-1">🎯 取色器功能 <a class="header-anchor" href="#🎯-取色器功能" aria-label="Permalink to &quot;🎯 取色器功能&quot;">​</a></h2><h3 id="启动取色" tabindex="-1">启动取色 <a class="header-anchor" href="#启动取色" aria-label="Permalink to &quot;启动取色&quot;">​</a></h3><ul><li>截图模式下按 <code>R</code> 或 <code>H</code></li><li>或右键托盘图标选择「取色器」</li></ul><h3 id="显示与复制" tabindex="-1">显示与复制 <a class="header-anchor" href="#显示与复制" aria-label="Permalink to &quot;显示与复制&quot;">​</a></h3><ul><li><code>R</code> / <code>H</code>：循环切换 RGB / HSV / HSL 显示模式</li><li><code>C</code>：复制当前显示模式的颜色值</li><li><code>1</code>：复制 HEX</li><li><code>2</code>：复制 RGB</li><li><code>3</code>：复制 HSL</li><li><code>4</code>：复制 HSV</li><li>鼠标左键：复制 HEX</li></ul><hr><h2 id="📌-贴图功能" tabindex="-1">📌 贴图功能 <a class="header-anchor" href="#📌-贴图功能" aria-label="Permalink to &quot;📌 贴图功能&quot;">​</a></h2><h3 id="截图贴回桌面" tabindex="-1">截图贴回桌面 <a class="header-anchor" href="#截图贴回桌面" aria-label="Permalink to &quot;截图贴回桌面&quot;">​</a></h3><p>截图后点击工具栏的贴图按钮，可将截图贴回桌面作为参考。</p><p><strong>特性</strong>：</p><ul><li>✅ 始终置顶</li><li>✅ 可拖拽移动</li><li>✅ 鼠标滚轮缩放</li><li>✅ 透明度调节</li><li>✅ 鼠标穿透</li></ul><h3 id="剪贴板贴图" tabindex="-1">剪贴板贴图 <a class="header-anchor" href="#剪贴板贴图" aria-label="Permalink to &quot;剪贴板贴图&quot;">​</a></h3><p>右键托盘图标选择「剪贴板贴图」，可将剪贴板中的位图创建为贴图窗口。</p><hr><h2 id="🎬-录屏功能" tabindex="-1">🎬 录屏功能 <a class="header-anchor" href="#🎬-录屏功能" aria-label="Permalink to &quot;🎬 录屏功能&quot;">​</a></h2><p>SnipX 支持轻量录屏帧序列采集。</p><p><strong>使用方法</strong>：</p><ol><li>右键托盘图标，选择「开始录屏」</li><li>再次打开托盘菜单，选择「停止录屏」</li><li>帧序列会保存到图片目录下的 <code>SnipXRecordings</code> 文件夹</li></ol><p><strong>说明</strong>：</p><ul><li>当前录屏实现以 PNG 帧序列为主</li><li>会生成基础 GIF 文件入口，完整高保真 GIF/视频编码可在后续版本增强</li><li>当前不录制音频</li></ul><hr><h2 id="⚙️-设置功能" tabindex="-1">⚙️ 设置功能 <a class="header-anchor" href="#⚙️-设置功能" aria-label="Permalink to &quot;⚙️ 设置功能&quot;">​</a></h2><h3 id="启动模式" tabindex="-1">启动模式 <a class="header-anchor" href="#启动模式" aria-label="Permalink to &quot;启动模式&quot;">​</a></h3><ul><li>托盘模式：启动后最小化到托盘</li><li>截图模式：启动后立即截图</li></ul><h3 id="开机自启" tabindex="-1">开机自启 <a class="header-anchor" href="#开机自启" aria-label="Permalink to &quot;开机自启&quot;">​</a></h3><p>可在设置中启用或关闭随 Windows 启动。</p><h3 id="托盘图标" tabindex="-1">托盘图标 <a class="header-anchor" href="#托盘图标" aria-label="Permalink to &quot;托盘图标&quot;">​</a></h3><p>可显示或隐藏系统托盘图标。</p><h3 id="保存设置" tabindex="-1">保存设置 <a class="header-anchor" href="#保存设置" aria-label="Permalink to &quot;保存设置&quot;">​</a></h3><p>支持默认格式、保存路径、JPG 质量、文件名前缀和自动保存目录配置。</p><h3 id="标注设置" tabindex="-1">标注设置 <a class="header-anchor" href="#标注设置" aria-label="Permalink to &quot;标注设置&quot;">​</a></h3><p>支持默认标注颜色和默认粗细配置。</p><hr><h2 id="🌍-多语言支持" tabindex="-1">🌍 多语言支持 <a class="header-anchor" href="#🌍-多语言支持" aria-label="Permalink to &quot;🌍 多语言支持&quot;">​</a></h2><p>SnipX 已接入轻量本地化模块，支持中文和英文文本。</p><hr><h2 id="📊-性能特性" tabindex="-1">📊 性能特性 <a class="header-anchor" href="#📊-性能特性" aria-label="Permalink to &quot;📊 性能特性&quot;">​</a></h2><ul><li>纯 C++17 + Win32 API + GDI+</li><li>无第三方运行时依赖</li><li>支持 MSVC、MinGW 和 CMake 构建</li><li>便携版可静态链接 MSVC runtime</li></ul><hr><h2 id="🔒-安全特性" tabindex="-1">🔒 安全特性 <a class="header-anchor" href="#🔒-安全特性" aria-label="Permalink to &quot;🔒 安全特性&quot;">​</a></h2><ul><li>完全本地运行</li><li>不收集用户数据</li><li>图片上传当前为本地导出待上传图片，不会自动上传到外部服务</li></ul><hr><div class="tip custom-block"><p class="custom-block-title">后续截图</p><p>基础网站资源已经提供；若要进一步丰富页面，可按 <a href="./SCREENSHOTS_NEEDED.html">截图需求清单</a> 将真实功能截图放到 <code>docs/public/screenshots/</code> 目录。</p></div>',122)])])}const b=e(o,[["render",h]]);export{p as __pageData,b as default};
